def basis(t, e, tau, kind):
    from scipy.signal import lfilter
    (t, e) = (np.asarray(t), np.asarray(e))
    (dt, de) = (np.diff(t), np.diff(e))
    z = dt[:, None] / tau
    q = np.exp(-z)
    if kind == 'ramp':
        u = de[:, None] * (-np.expm1(-z) / z)
    elif kind == 'right':
        u = np.broadcast_to(de[:, None], z.shape)
    elif kind == 'left':
        u = de[:, None] * q
    elif kind == 'mid':
        u = de[:, None] * np.exp(-z / 2)
    elif kind == 'trap':
        v = np.gradient(e, t)
        u = dt[:, None] * (q * v[:-1, None] + v[1:, None]) / 2
    elif kind == 'gradient':
        v = np.gradient(e, t)
        u = dt[:, None] * v[1:, None] * np.ones(len(tau))
    h = np.zeros((len(t), len(tau)))
    if np.allclose(dt, dt[0], rtol=1e-11, atol=0):
        for j in range(len(tau)):
            h[1:, j] = lfilter([1.0], [1.0, -q[0, j]], u[:, j])
    else:
        for j in range(1, len(t)):
            h[j] = q[j - 1] * h[j - 1] + u[j - 1]
    return np.column_stack((e, h))
